const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;
const n = input[idx++];
const m = input[idx++];

const MOD = 998244353;
const MAX_N = 2 * 10 ** 5 + 1;

// Construct factorial table
const fac = new Array(MAX_N + 1);
fac[0] = 1;
for (let i = 1; i <= MAX_N; i++) {
    fac[i] = fac[i - 1] * i % MOD;
}

const fac_inv = new Array(MAX_N + 1);
fac_inv[0] = 1;

// fast pow with mod
function modPow(base, exp, mod) {
    base %= mod;
    let res = 1n;
    let b = BigInt(base);
    let e = BigInt(exp);
    let m = BigInt(mod);
    while (e > 0n) {
        if (e & 1n) res = res * b % m;
        b = b * b % m;
        e >>= 1n;
    }
    return Number(res);
}

fac_inv[MAX_N] = modPow(fac[MAX_N], MOD - 2, MOD);
for (let i = MAX_N; i >= 2; i--) {
    fac_inv[i - 1] = fac_inv[i] * i % MOD;
}

function mod_nCr(nv, rv) {
    if (nv < rv || nv < 0 || rv < 0) return 0;
    const tmp = fac_inv[nv - rv] * fac_inv[rv] % MOD;
    return tmp * fac[nv] % MOD;
}

let ans;
if (n - 3 > 0) {
    ans = mod_nCr(m, n - 1) * (n - 2) % MOD;
    ans = ans * modPow(2, n - 3, MOD) % MOD;
} else {
    ans = mod_nCr(m, n - 1) * (n - 2) % MOD;
}
ans %= MOD;

console.log(ans.toString());

